import { createProjectDiscoveryConfig } from "../discovery/project-discovery-config.js";
import { discoverSourceTriggers, } from "../trigger/discovery.js";
import { isWebhookDefinition } from "./types.js";
import { normalizeWebhookDefinition } from "./validation.js";
/** Discover and validate source-defined webhooks across configured directories. */
export async function discoverWebhooks(options) {
    const triggerDirs = options.webhooksDir === undefined
        ? createProjectDiscoveryConfig({
            projectDir: options.projectDir,
            config: options.config,
        }).webhookDirs
        : [options.webhooksDir];
    return await discoverSourceTriggers({
        projectDir: options.projectDir,
        adapter: options.adapter,
        config: options.config,
        triggerDirs,
        sourceKind: "webhook",
        validate: isWebhookDefinition,
        normalize: normalizeWebhookDefinition,
        allowHostProjectCodeExecution: options.allowHostProjectCodeExecution,
    });
}
